import {lessonCheck,publicCheck} from './lesson-checks.js';
import {sessionRequest,logout,escapeText as esc} from './account.js';
import {topics,initial,apply,prepare,baseline,unlocked,diagnosticQuestion,unitQuestion,correct,nextSessions,supportFor,SLIDE_COUNT} from './learning-core.js';
import {lessonSlides} from './classroom-content.js';
import {math,rich,fraction,spoken} from './math.js';
import {companions,companionFor,calculate,thinkingTurn,rewardSummary,mathFromSpeech} from './classroom-tools.js';
const $=s=>document.querySelector(s),root=$('#learning-root');
let user,lang='tr',data,state,revision=0,busy=false,feedback=null,selected='',voice=false,mic=null,local=false,localKey='',page=location.hash.slice(1)||'discover',chatBusy=false,boardMode='lesson',revealed=0,readingToken=0,coachError='',pendingDraft=null;
const w=(tr,en)=>lang==='tr'?tr:en,title=id=>topics.find(t=>t.id===id)?.title[lang]||id;
const labels=()=>({discover:w('Keşif atölyesi','Discovery studio'),route:w('Öğrenme rotam','My learning path'),plan:w('Çalışma planım','My study plan'),progress:w('Gelişimim','My progress')});
const notice=text=>{const n=$('#notice');n.textContent=text;n.style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>n.style.display='none',6000)};
function questionTable(table){return `<div class="problem-table"><table><thead><tr>${table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function courseHeader(id,u){const slides=lessonSlides(id,lang);return `<section class="course-header"><div><span class="eyebrow">${w('ÖNCE KONU ANLATIMI','TOPIC LESSON FIRST')}</span><h2>${w('Birlikte anlayarak ilerleyelim.','Build understanding together.')}</h2><p>${w('15–20 dakikalık ders planı · Anlatım, tahta örnekleri ve üç düşünme molası. Süre, senin hızına göre değişir.','A 15–20 minute lesson plan · Explanation, board examples and three thinking breaks. Actual time depends on your pace.')}</p><span class="pill">${w('Bölüm','Section')} ${u.slide+1} / ${slides.length} · ~${slides[u.slide].minutes} ${w('dk','min')}</span></div><button type="button" class="button" id="course-start">▶ ${u.slide===0?w('Dersi başlat','Start the lesson'):w('Buradan anlatmaya devam et','Continue explaining here')}</button><button type="button" class="button secondary" id="course-restart">${w('Baştan başlat','Restart the lesson')}</button><details class="course-outline"><summary>${w('Dersin tamamını gör · yaklaşık 19 dk','View the full lesson plan · about 19 min')}</summary><ol>${slides.map((slide,i)=>`<li class="${i===u.slide?'current':''}"><span>${esc(slide.title)}</span><b>~${slide.minutes} ${w('dk','min')}</b></li>`).join('')}</ol></details></section>`}
function bindCourse(id,u){if(!$('#course-start'))return;$('#course-start').onclick=()=>{if(busy||chatBusy)return;lessonAuto=true;voice=true;render();startCourseSlide(id)};$('#course-restart').onclick=async()=>{lessonAuto=false;stopSpeech();if(await act('review',{topic:id})){lessonAuto=true;voice=true;render();startCourseSlide(id)}}}
function startCourseSlide(id){const u=state.units[id];if(!lessonAuto||selected!==id||page!=='route'||u?.mode!=='lesson')return;const index=u.slide,slide=lessonSlides(id,lang)[index];playBoard({speech:slide.speech,steps:slide.lines,question:data.checks?.[id]?.text||slide.prompt},'#whiteboard',false,()=>advanceCourse(id,index))}
async function advanceCourse(id,index){const u=state.units[id];if(!lessonAuto||selected!==id||page!=='route'||u?.mode!=='lesson'||u.slide!==index)return;if(data.checks?.[id]&&!u.checks?.[index]?.correct){$('#lesson-check-form')?.scrollIntoView?.({behavior:'smooth',block:'center'});notice(w('Şimdi sıra sende. Cevabını paylaşınca derse devam edeceğim.','Your turn. I will continue the lesson after you share your answer.'));return}if(await act('next-slide',{topic:id})){if(state.units[id].mode==='lesson')startCourseSlide(id);else {lessonAuto=false;notice(w('Konu anlatımı bitti. Şimdi birlikte soru çözebiliriz.','The lesson is complete. Now we can solve problems together.'))}}else lessonAuto=false}

function lessonCheckpoint(id,u){const q=data.checks?.[id],saved=u.checks?.[u.slide];if(!q)return '';return `<section class="lesson-check"><span class="eyebrow">${w('MOLİ BURADA DURUYOR','MOLİ PAUSES HERE')}</span><h3>${w('Şimdi senin fikrin','Your turn to think')}</h3><form id="lesson-check-form"><fieldset><legend>${rich(q.text)}</legend>${q.choices.map(x=>`<label class="check"><input type="radio" name="lesson-check" required value="${x.value}" ${saved?.value===x.value?'checked':''}>${rich(x.text)}</label>`).join('')}</fieldset><button class="button" type="submit">${w('Düşüncemi paylaş','Share my thinking')}</button></form>${saved?`<p class="check-result ${saved.correct?'success':''}" role="status">${saved.correct?w('Evet! Bu ilişkiyi kurduk. Şimdi devam edebiliriz.','Yes! You made the connection. We can continue.'):w('Bir daha düşünelim. Yukarıdaki açıklama ve tahta adımları sana yardımcı olabilir. MOLİ’ye de sorabilirsin.','Let’s think again. The explanation and board steps can help; you can also ask MOLİ.')}</p>`:''}</section>`}
function bindLessonCheck(id,u){if(!$('#lesson-check-form'))return;$('#lesson-check-form').onsubmit=async e=>{e.preventDefault();const value=$('input[name=lesson-check]:checked')?.value;if(value===undefined)return;const q=data.checks[id];if(await act('lesson-check',{topic:id,id:q.id,value})){const ok=state.units[id].checks[u.slide]?.correct;if(ok){if(lessonAuto)await advanceCourse(id,u.slide);else speak(w('Güzel! Nedenini yakaladın.','Good! You found the reason.'));}else {tutorOpen=true;render();speak(w('Birlikte bir kez daha inceleyelim.','Let’s take another look together.'))}}}}
let chalkTimers=[];
function clearChalk(){for(const timer of chalkTimers)clearTimeout(timer);chalkTimers=[];root?.querySelectorAll('.chalk-glyph').forEach(el=>el.replaceWith(document.createTextNode(el.textContent)));root?.querySelectorAll('.chalk-cursor').forEach(el=>el.remove())}
function writeChalk(el,board,token){if(!el||!document.createTreeWalker||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const walker=document.createTreeWalker(el,4),nodes=[];let node;while((node=walker.nextNode()))if(node.textContent.trim()&&!node.parentElement?.closest('.katex-mathml,.chalk-index'))nodes.push(node);const glyphs=[];for(const node of nodes){const fragment=document.createDocumentFragment();for(const character of Array.from(node.textContent)){const span=document.createElement('span');span.className='chalk-glyph';span.textContent=character;span.style.opacity='0';glyphs.push(span);fragment.appendChild(span)}node.replaceWith(fragment)}const cursor=document.createElement('span');cursor.className='chalk-cursor';cursor.setAttribute('aria-hidden','true');board.appendChild(cursor);const step=Math.min(22,5500/Math.max(1,glyphs.length));glyphs.forEach((span,i)=>chalkTimers.push(setTimeout(()=>{if(token!==readingToken)return;span.style.opacity='1';if(span.getBoundingClientRect&&board.getBoundingClientRect){const r=span.getBoundingClientRect(),b=board.getBoundingClientRect();cursor.style.left=(r.right-b.left+3)+'px';cursor.style.top=(r.bottom-b.top-7)+'px'}if(i===glyphs.length-1)cursor.remove()},i*step)));}
function celebrate(before,after){if(after.points<=before.points)return;const earned=after.points-before.points,newBadge=after.badges.find(b=>b.earned&&!before.badges.find(x=>x.id===b.id)?.earned),toast=document.createElement('div');toast.className='xp-celebration';toast.setAttribute('role','status');toast.innerHTML=`<span class="celebration-star">✦</span><div><strong>+${earned} XP</strong><span>${newBadge?w(newBadge.tr,newBadge.en):after.level>before.level?w('Yeni seviye: ','New level: ')+after.level:w('Bir fikir daha yerine oturdu!','Another idea connected!')}</span></div>${Array.from({length:12},(_,i)=>`<i style="--i:${i}"></i>`).join('')}`;document.body.appendChild(toast);setTimeout(()=>toast.remove(),3600)}

function fmt(n){return Number(n).toLocaleString(lang==='tr'?'tr-TR':'en-US',{maximumFractionDigits:4})}
function date(iso){return new Intl.DateTimeFormat(lang==='tr'?'tr-TR':'en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:state.plan?.zone||'Europe/Istanbul'}).format(new Date(iso))}
let lessonAuto=false,tutorOpen=false,toolOpen='',cancelThink=null,turnDeadline=0,turnReady=true,playTimer=null,pendingQuestion=null;
function stopSpeech(){readingToken++;clearTimeout(playTimer);clearChalk();root?.querySelectorAll('.is-writing').forEach(el=>el.classList.remove('is-writing'));if('speechSynthesis'in window)window.speechSynthesis.cancel()}
function speak(text,onend){if(!voice||!('speechSynthesis'in window)){onend?.();return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(spoken(text,lang));u.lang=lang==='tr'?'tr-TR':'en-US';u.rate=.94;if(onend)u.onend=onend;u.onerror=()=>{onend?.();notice(w('Sesli okuma durdu. Tahtadaki adımları yazılı takip edebilirsin.','Audio stopped. You can follow the written board steps.'))};window.speechSynthesis.speak(u)}
function localView(){prepare(state);return {state,revision,diagnosticQuestion:state.diagnostic.done?null:diagnosticQuestion(state,lang),questions:Object.fromEntries(Object.keys(state.units).map(id=>[id,unitQuestion(state,id,lang)])),checks:Object.fromEntries(Object.entries(state.units).map(([id,u])=>[id,u.mode==='lesson'?publicCheck(lessonCheck(id,u.slide,lang)):null])),support:Object.fromEntries(Object.keys(state.units).map(id=>[id,supportFor(state,id,lang)])),capabilities:{cloud:false,ai:false,email:false,sms:false}}}
async function refresh(){if(local){data=localView();return}const r=await fetch('/api/learning?language='+lang,{credentials:'same-origin',cache:'no-store'}),j=await r.json();if(!r.ok)throw new Error(j.error);data=j;state=prepare(j.state);revision=j.revision}
async function act(action,p={}){if(busy||chatBusy)return false;busy=true;if(['hint','notes','show-solution'].includes(action))captureDraft();root.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);try{if(local){const q=action==='answer'?unitQuestion(state,p.topic,lang):null;if(action!=='minutes')feedback=q&&state.units[p.topic]?.mode!=='test'?{correct:correct(q,p.value),hint:correct(q,p.value)?'':q.hint,assisted:!!state.units[p.topic]?.shownSolutions?.[q.id]}:null;apply(state,action,p,lang);revision++;try{localStorage.setItem(localKey,JSON.stringify(state))}catch{notice(w('Bu cihazda kayıt tutamıyoruz. Ayrılmadan önce raporunu indir.','This device cannot save. Export your records before leaving.'))}data=localView()}else{const r=await fetch('/api/learning',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...p,revision,language:lang})}),j=await r.json();if(!r.ok)throw new Error(j.error);data=j;state=prepare(j.state);revision=j.revision;if(action!=='minutes')feedback=j.feedback}
 if(action!=='minutes'){render();if(['hint','notes','show-solution'].includes(action))restoreDraft()}return true;
 }catch(e){notice(e.message==='reload_required'?w('Başka bir sekmede kayıt değişti. Güncel kayıtları yükledim; cevabını yeniden gönderebilirsin.','Another tab changed the record. The latest version is loaded; you can resubmit.'):w('İşlem kaydedilemedi. Tekrar dene.','Could not save. Please retry.'));try{await refresh();if(action!=='minutes')render()}catch{}return false}finally{busy=false;root.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=b.id==='coach-submit'&&!turnReady)}}
function go(p){lessonAuto=false;cancelTurn();tutorOpen=false;pendingQuestion=null;feedback=null;stopSpeech();location.hash=p;if(page===p)render()}
function button(text,id,secondary=false){return `<button type="button" id="${id}" class="button ${secondary?'secondary':''}">${text}</button>`}
function layout(content){const l=labels();root.innerHTML=`<div class="layout" style="--companion:${companionFor(state.companion).color};--companion-ink:${companionFor(state.companion).ink}"><aside class="rail"><a class="logo" href="#discover"><span class="logo-face">m</span> MOLİ<i>.</i></a><span class="rail-label">${w('ÖĞRENME ALANIM','MY LEARNING SPACE')}</span><nav>${Object.entries(l).map(([key,label],i)=>`<a href="#${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><span aria-hidden="true">${['◇','⌘','▦','◴'][i]}</span>${label}</a>`).join('')}</nav><div class="rail-bottom"><strong>${w('Anla. Düşün. Kendi yolunu bul.','Understand. Think. Find your way.')}</strong>${esc(user?.name||w('Misafir öğrenci','Guest learner'))}<span class="status">${w('8. sınıf matematik','Grade 8 mathematics')}</span></div></aside><div class="workspace"><header class="topbar"><span>${w('Matematik','Mathematics')} / <b>${l[page]||l.route}</b></span><div><button class="reward-chip" id="rewards" aria-label="${w('Puanlarım ve rozetlerim','My points and badges')}">✦ ${rewardSummary(state).points} XP</button><button class="button small secondary" id="voice" aria-pressed="${voice}">${voice?'♫':'♪'} ${w(voice?'Ses açık':'Sesi aç',voice?'Voice on':'Enable voice')}</button><button class="button small secondary" id="language">${lang.toUpperCase()}</button>${user?`<a href="/?view=account">${w('Hesabım','My account')}</a><button class="button link" id="logout">${w('Çıkış','Sign out')}</button>`:`<a href="/">${w('Giriş yap','Sign in')}</a>`}</div></header>${local?`<div class="save-warning">${user?w('Cihaz içi pilot kaydı · Hesaba senkronizasyon şu anda etkin değil.','Device-only pilot · Cloud sync is not active.'):w('Misafir denemesi · Kayıtların bu tarayıcıda tutulur.','Guest preview · Records stay in this browser.')} <button class="button link" id="retry-cloud">${w('Yeniden bağlan','Reconnect')}</button></div>`:''}<main class="content">${page==='route'&&state.diagnostic.done?journeyBanner():''}${content}<footer>${w('MOLİ · Matematiği anlamak için birlikte düşünüyoruz.','MOLİ · Thinking together to understand mathematics.')}</footer></main></div></div>`;
 $('#language').onclick=async()=>{if(busy||chatBusy)return;lessonAuto=false;cancelTurn();stopSpeech();captureDraft();lang=lang==='tr'?'en':'tr';try{localStorage.setItem('moli.language',lang)}catch{}feedback=null;await refresh();render();restoreDraft()};$('#voice').onclick=()=>{if(!('speechSynthesis'in window)){notice(w('Bu tarayıcıda sesli okuma bulunmuyor.','Speech playback is unavailable in this browser.'));return}voice=!voice;$('#voice').setAttribute('aria-pressed',String(voice));$('#voice').textContent=w(voice?'♫ Ses açık':'♪ Sesi aç',voice?'♫ Voice on':'♪ Enable voice');if(voice)speak($('#spoken')?.getAttribute('data-speech')||$('#spoken')?.textContent||w('Merhaba, birlikte düşünmeye hazırım.','Hello, I’m ready to think with you.'));else {lessonAuto=false;stopSpeech()}};if($('#logout'))$('#logout').onclick=logout;if($('#retry-cloud'))$('#retry-cloud').onclick=()=>location.reload();$('#rewards').onclick=showRewards;if($('#journey-rewards'))$('#journey-rewards').onclick=showRewards;document.documentElement.lang=lang;
}
function captureDraft(){pendingDraft={answer:$('#answer-value')?.value||'',question:$('#coach-input')?.value||''}}
function restoreDraft(){if(!pendingDraft)return;for(const [selector,key]of [['#answer-value','answer'],['#coach-input','question']])if($(selector))$(selector).value=pendingDraft[key];pendingDraft=null}
function intro(heading,desc){return `<div class="eyebrow">${w('SENİN HIZINDA, BİRLİKTE','TOGETHER, AT YOUR PACE')}</div><h1>${heading}</h1><p class="lead">${desc}</p>`}
function chart(){return `<div class="legend"><span>● ${w('Başlangıç yanıtları','Starting responses')}</span><span>│ ${w('Çalışma hedefi: %80','Practice target: 80%')}</span></div><div class="bars" role="img" aria-label="${w('Konu bazında başlangıç grafiği, çalışma hedefi yüzde 80','Starting skill chart by topic; practice target 80 percent')}">${baseline(state).map(t=>`<div><div class="bar-label"><span>${esc(t.title[lang])}</span><b>${t.score===null?'—':t.score+'%'}</b></div><div class="bar-track"><div class="bar-fill" style="width:${t.score||0}%"></div><div class="bar-target"></div></div></div>`).join('')}</div><p class="subtle">${w('Her konuda iki soru: başlangıç örneklemi, kesin bir yetenek veya LGS puanı ölçümü değil. %80, konu çalışmalarımız için seçtiğimiz hedeftir.','Two questions per topic: a starting sample, not an ability label or LGS score. 80% is our chosen practice target.')}</p>`}
function moliAvatar(){return '<div class="moli-avatar" aria-hidden="true"><span class="antenna"></span><i></i><i></i><b>⌣</b></div>'}
function neutralCoach(){return `<aside class="moli-panel neutral"><div class="moli-identity">${moliAvatar()}<div><h2>MOLİ</h2><span class="status">${w('Seni tanıyorum','Getting to know you')}</span></div></div><div class="coach-line">${w('Bu bölümde soruları kendi başına çözmeni istiyorum. Bilmediğinde “Henüz bilmiyorum” diyebilirsin. Bitirince sonuçlarına birlikte bakıp derslere başlayacağız.','Work independently in this part. You can say “I don’t know yet.” Afterwards, we will review the results and begin learning together.')}</div><p class="subtle">${w('Çözüm yardımı kapalı · Soruyu sesli dinleyebilirsin.','Solution assistance is off · You can listen to the question.')}</p></aside>`}
function questionForm(q,diagnostic=false){return `<form id="answer-form" data-question="${esc(q.id)}"><div class="question-navigation"><div class="question-top-actions">${button(w('▦ Hesap makinesi','▦ Calculator'),'calculator',true)}<span class="subtle">${pendingQuestion?w('Yanıtın kaydedildi','Answer saved'):w('Düşünmek için zamanın var','Take your time')}</span></div>${pendingQuestion?button(w('Sonraki soru / adım →','Next question / step →'),'next-question'):`<button class="button" type="submit">${w(diagnostic?'Yanıtla ve ilerle →':'Yanıtımı gönder →',diagnostic?'Answer and continue →':'Submit my answer →')}</button>`}</div><span class="reading-goal">${esc(q.readingGoal||'')}</span><div class="question" id="spoken" data-speech="${esc(q.text)}">${rich(q.text)}</div>${q.table?questionTable(q.table):''}${q.visual?visual(q.visual,q):''}${q.open?`<label class="field answer-field"><span class="answer-label"><b>✎</b> ${w('Cevabını buraya yaz','Write your answer here')}</span><input id="answer-value" aria-describedby="answer-help" required maxlength="100" autocomplete="off" aria-label="${w('Matematik cevabın','Your mathematical answer')}" placeholder="${w('Cevabını yaz veya matematik klavyesini kullan','Type or use the math keyboard')}"><span id="answer-help">${!diagnostic&&state.units[selected]?.mode!=='test'?w('Başlayamıyorsan MOLİ’ye sor. Önce yazman gerekmiyor.','If you cannot start, ask MOLİ. You do not need to write first.'):w('Bir sayı, kesir veya matematik ifadesi yazabilirsin.','You can enter a number, fraction or mathematical expression.')}</span></label><output id="answer-preview" aria-live="polite"></output>`:`<fieldset class="question-choices"><legend class="subtle">${w('Bir cevap seç','Choose one answer')}</legend><div class="choices">${q.choices.map((n,i)=>`<label class="choice"><input type="radio" name="choice" value="${n}" required><span><b>${String.fromCharCode(65+i)}</b> ${math(fraction(n))}</span></label>`).join('')}</div></fieldset>`}<div class="question-toolstrip">${button(w('Soruyu dinle','Listen to question'),'listen',true)}${button(w('⌨ Matematik klavyesi','⌨ Math keyboard'),'math-keyboard',true)}${!diagnostic&&state.units[selected]?.mode!=='test'&&!pendingQuestion?`<button type="button" class="button ask-inline" id="toggle-moli" aria-expanded="${tutorOpen}" aria-controls="tutor-studio">✦ ${w('MOLİ’ye sor','Ask MOLİ')}</button>`:''}</div><div id="math-tools"></div></form>`}
function bindQuestion(q,diagnostic=false){$('#answer-form').onsubmit=async e=>{e.preventDefault();if(pendingQuestion)return;const value=q.open?$('#answer-value').value:$('input[name=choice]:checked')?.value;if(!value?.trim())return;cancelTurn();stopSpeech();tutorOpen=false;boardMode='lesson';revealed=0;const wasTest=selected&&state.units[selected]?.mode==='test',before=selected?JSON.parse(JSON.stringify(state.units[selected])):null,oldReward=rewardSummary(state),oldPoints=oldReward.points;
 if(await act(diagnostic?'diagnostic':'answer',{topic:q.topic,id:q.id,value})){if(!diagnostic&&(wasTest||(feedback?.correct&&!feedback.assisted))){pendingQuestion={q,u:before,value};render();const field=$('#answer-value');if(field){field.value=value;answerPreview()}root.querySelectorAll('#answer-form input').forEach(x=>{if(x.type==='radio')x.checked=x.value===value;x.disabled=true})}
 if(!diagnostic&&!wasTest&&feedback){if(feedback.correct&&feedback.assisted){notice(w('Çözümü gördük. Şimdi benzer bir soruda sen deneyebilirsin.','We have seen the solution. Try a similar problem next.'))}else if(feedback.correct){const earned=rewardSummary(state).points-oldPoints;celebrate(oldReward,rewardSummary(state));notice(w(earned?`Harika bir adım! +${earned} XP ✦`:'Bu fikri pekiştirdin!','Great reasoning! '+(earned?`+${earned} XP ✦`:'')));speak(w('İlişkiyi doğru kurdun. Bir adım daha ilerledin.','You found the relationship. Another step forward.'))}else {tutorOpen=true;render();if($('#answer-value')){$('#answer-value').value=value;answerPreview()}playBoard(tutorContent(selected),'#tutor-board',true)}}
 if(diagnostic&&state.diagnostic.done)speak(w('Başlangıç haritan hazır. Şimdi birlikte ilerleyebiliriz.','Your starting map is ready. Let’s learn together.'))}};
 $('#listen').onclick=()=>{voice=true;speak(q.text)};if($('#next-question'))$('#next-question').onclick=()=>{pendingQuestion=null;feedback=null;toolOpen='';boardMode='lesson';revealed=0;render();window.scrollTo(0,0)};
 if($('#answer-value')){$('#answer-value').oninput=answerPreview};
 if($('#answer-mic'))$('#answer-mic').onclick=()=>startMicrophone('answer-value');bindTools();
}
function answerPreview(){const field=$('#answer-value'),out=$('#answer-preview');if(!field||!out)return;const value=field.value.trim();if(!value){out.innerHTML='';return}if(!/^[0-9+*/^().,\s\-sqrtpi√²×÷−]+$/.test(value)){out.textContent=w('Matematik sembollerini kullan. Sesle yazılan cevabını kontrol et.','Use math symbols. Review any transcribed answer.');return}const simple=value.match(/^\(?([+-]?[\d.,]+)\)?\/\(?([+-]?[\d.,]+)\)?$/);out.innerHTML=simple?math(`\\frac{${simple[1]}}{${simple[2]}}`):math(value.replaceAll('*','\\cdot ').replaceAll('/','\\div ').replace(/sqrt\(([^()]*)\)/g,'\\sqrt{$1}').replaceAll('pi','\\pi '))}
function discover(){if(!state.diagnostic.started){layout(intro(w('Önce nereden başlayacağını bulalım.','Let’s find your starting point.'),w('Durumları yorumladığın, ilişkiler kurduğun 26 kısa soruyla seni tanıyacağım. Sonra birlikte öğrenme rotanı ve çalışma planını oluşturacağız.','I will get to know you through 26 short questions about interpreting situations and connecting ideas. Then we will build your learning path and study plan.'))+`<div class="classroom-grid question-stage"><section class="card hero"><span class="pill">${w('26 soru · Kendi hızında','26 questions · At your own pace')}</span><h2>${w('Bu bir yarış değil.','This is not a race.')}</h2><p id="spoken">${w('Bazı sorular seçenekli, bazılarında cevabını sen yazacaksın. Soruları yardım almadan çözmen, sana daha uygun bir başlangıç seçmemizi sağlayacak. Bilmediğinde geçebilirsin.','Some questions have choices; others ask for your own answer. Solving independently helps us choose a better starting point. You can skip questions you do not know.')}</p>${button(w('Seviyemi keşfedelim →','Discover my starting point →'),'start')}</section>${neutralCoach()}</div>`);$('#start').onclick=()=>act('start');return}
 if(state.diagnostic.done){layout(intro(w('Başlangıç haritan hazır.','Your starting map is ready.'),w('Sonuçlar bir etiket değil, birlikte hangi konulara odaklanacağımızın işareti.','These results are not a label; they help us choose what to work on together.'))+`<div class="grid"><section class="card"><h2>${w('Bugünkü başlangıç noktan','Your starting point today')}</h2>${chart()}</section><section><div class="card hero">${moliAvatar()}<p id="spoken">${w('Her konuda iki soruya baktık. Bazı fikirler sağlam, bazılarını beraber güçlendireceğiz. Önce bir durumu anlamaya, sonra neden o işlemi yaptığımızı açıklamaya çalışacağız.','We sampled two questions per topic. Some ideas are already strong; others we will build together. We will understand situations first, then explain why our methods work.')}</p>${button(w('Öğrenme rotama geç →','Open my learning path →'),'to-route')}<div class="actions">${button(w('Programımı oluşturalım','Build my study plan'),'to-plan',true)}</div></div><div class="card"><h3>${w('Derslerimiz nasıl ilerleyecek?','How will lessons work?')}</h3><ol class="journey"><li>${w('MOLİ tahtada anlatır, sen her adımda soru sorabilirsin.','MOLİ explains on the board; ask questions at any step.')}</li><li>${w('Bir soruyu önce sen denersin, gerekirse birlikte çözeriz.','Try a problem first, then work together when needed.')}</li><li>${w('Sonunda bağımsız testle ne öğrendiğine bakarız.','An independent test checks what you learned.')}</li></ol></div></section></div>`);$('#to-route').onclick=()=>go('route');$('#to-plan').onclick=()=>go('plan');return}
 const q=data.diagnosticQuestion;layout(intro(w('Bir soruyla başlayalım.','One question at a time.'),w('Soruyu anla, gerekli bilgiyi seç ve kendi yolunu dene.','Understand the situation, choose the useful information and try your own approach.'))+`<div class="classroom-grid question-stage"><section class="card question-card"><div class="panel-topline"><span class="pill">${state.diagnostic.answers.length+1} / 26</span><span class="pill">${esc(title(q.topic))}</span></div><div class="progress"><span style="width:${state.diagnostic.answers.length/26*100}%"></span></div>${questionForm(q,true)}<div class="actions">${button(w('Henüz bilmiyorum, geç','I don’t know yet — skip'),'skip',true)}</div></section>${neutralCoach()}</div>`);bindQuestion(q,true);$('#skip').onclick=()=>act('diagnostic',{id:q.id,value:'skip'});
}
function gate(){layout(intro(w('Önce başlangıç noktanı bulalım.','Let’s find your starting point first.'),w('Kişisel rota ve program için Keşif atölyesini tamamla.','Complete the discovery assessment to unlock your personal path and plan.'))+`<div class="card">${button(w('Keşif atölyesine git →','Open the discovery studio →'),'gate')}</div>`);$('#gate').onclick=()=>go('discover')}
function route(){if(!state.diagnostic.done)return gate();if(selected&&state.units[selected])return lesson();const next=state.order.find(id=>!state.units[id]?.passed);layout(intro(w('Sınıfın hazır. Birlikte başlayalım.','Your classroom is ready. Let’s begin.'),w('Anlatımı dinle, tahtayı takip et, sorunu sor. Önce birlikte, sonra kendi başına çöz.','Listen, follow the board and ask questions. Solve together first, then independently.'))+`<section class="card hero"><span class="pill">${w('Sıradaki konu','Up next')}</span><h2>${next?esc(title(next)):w('Başlangıç rotanı tamamladın!','You completed your initial path!')}</h2><p>${w('Tahtada anlatım → Birlikte çözüm → Bağımsız test → Bir sonraki konu.','Board explanation → Guided solving → Independent test → Next topic.')}</p>${next?button(w('Derse gir →','Enter classroom →'),'continue'):''}</section><section class="card"><h2>${w('Kişisel öğrenme rotan','Your learning path')}</h2>${state.order.map((id,i)=>{const u=state.units[id],canOpen=unlocked(state,id);return `<div class="topic ${canOpen?'':'locked'}"><span class="topic-number">${u?.passed?'✓':i+1}</span><div><strong>${esc(title(id))}</strong><span class="subtle">${u?.passed?w('Tamamlandı','Completed'):canOpen?w('Öğrenmeye hazır','Ready to learn'):w('Önceki konuyu tamamladığında açılır','Opens after the previous topic')}${u?.attempts.length?' · '+w('Son test: ','Latest test: ')+u.attempts.at(-1).score+'%':''}</span></div>${canOpen?`<button class="button small secondary" data-open="${id}">${w('Sınıfa gir →','Enter →')}</button>`:'<span aria-hidden="true">⌑</span>'}</div>`}).join('')}</section>`);root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openUnit(b.dataset.open));if($('#continue'))$('#continue').onclick=()=>openUnit(next)}
