function notes(id,u){return `<details class="card board-notes"><summary>${w('Kendi düşünme alanım','My thinking space')}</summary><label class="field">${w('Bir ilişki, tahmin veya çözüm adımı not et.','Note a relationship, prediction or solution step.')}<textarea id="board-notes" maxlength="3000">${esc(u.notes||'')}</textarea></label>${button(w('Notumu kaydet','Save my note'),'save-notes',true)}</details>`}
