function cancelTurn(){cancelThink?.();cancelThink=null;turnReady=true;turnDeadline=0;}
function startThink(){cancelTurn();if(!$('#coach-form'))return;turnReady=false;turnDeadline=Date.now()+10000;cancelThink=thinkingTurn({onTick:left=>{if($('#turn-status'))$('#turn-status').textContent=left?w(`Sıra sende · ${left} sn düşünme zamanı. Yazabilir veya konuşabilirsin.`,`Your turn · ${left}s to think. You can type or speak.`):w('Seni dinliyorum. Hazır olunca düşünceni gönder; sessizlikte cevap vermeyeceğim.','I’m listening. Send your idea when ready; silence won’t trigger a reply.');if($('#coach-submit'))$('#coach-submit').disabled=left>0},onReady:()=>{turnReady=true;turnDeadline=0}})}
function playBoard(content,selector,ask,onComplete){cancelTurn();stopSpeech();const token=readingToken,board=$(selector);if(!board)return;board.classList.add('is-writing');turnReady=false;if($('#coach-submit'))$('#coach-submit').disabled=true;board.querySelectorAll('[data-board-index]').forEach(el=>el.classList.remove('written'));const lines=content.steps||content.lines||[];
 const segment=(text,next)=>{let ended=false;const done=()=>{if(ended||token!==readingToken)return;ended=true;clearTimeout(playTimer);next()};if(voice&&'speechSynthesis'in window){playTimer=setTimeout(done,Math.min(65000,Math.max(3000,String(text).length*95)));speak(text,done)}else playTimer=setTimeout(done,Math.min(14000,Math.max(1800,String(text).length*25)))};
 const finish=()=>{if(token!==readingToken)return;board.classList.remove('is-writing');segment(content.question||'',()=>{if(ask)startThink();else {turnReady=true;if($('#coach-submit'))$('#coach-submit').disabled=false;}onComplete?.()})};
 const line=i=>{if(token!==readingToken)return;if(i>=lines.length)return finish();const el=board.querySelector(`[data-board-index="${i}"]`);el?.classList.add('written');writeChalk(el,board,token);const x=lines[i];segment([x.note||x.explanation||x.text,x.math].filter(Boolean).join(' '),()=>line(i+1))};const introduction=lines.reduce((text,x)=>x.text?text.replace(x.text,''):text,content.speech||'').trim();if(introduction)segment(introduction,()=>line(0));else line(0);
}
function tutorContent(id){const u=state.units[id],c=companionFor(state.companion),reply=boardMode==='ai'?u.boardReplies?.at(-1):null,support=data.support?.[id];if(reply)return reply;if(support?.full)return {title:w('Sorunun tamamını birlikte çözelim','Let’s solve the whole problem'),speech:w('Hiç başlayamaman sorun değil. Önce soruda verilenleri ayıracağım, sonra her işlemin nedenini açıklayarak sonuca ulaşacağım. Bitince benzer bir soruyu sen deneyeceksin.','It is fine if you cannot start. I will identify the given facts, explain each calculation and reach the result. Afterwards, you can try a similar problem.'),steps:support.steps,question:w('Çözüm tamamlandı. Hazır olduğunda “Benzer soruyu ben deneyeyim” düğmesine bas.','The solution is complete. When ready, choose “Let me try a similar problem”.')};return {title:w('Birlikte öğrenelim','Let’s learn together'),speech:u.mode==='lesson'?w('Konuyu açıklamak için buradayım. Bir satırı sorabilir veya dersi başlatabilirsin.','I am here to explain the topic. Ask about a step or start the lesson.'):w('Ben '+c.name+'. Sorunun tamamını tahtada açıklayabilirim.','I’m '+c.name+'. I can explain the whole solution on the board.'),steps:support?.steps||[],question:w('Neyi açıklamamı istersin?','What would you like me to explain?')}}
async function openSolution(id){if(busy||chatBusy)return;const q=data.questions[id];if(!q)return;lessonAuto=false;cancelTurn();stopSpeech();captureDraft();tutorOpen=true;boardMode='lesson';revealed=0;voice=true;if(await act('show-solution',{topic:id,id:q.id})){restoreDraft();$('#tutor-studio')?.scrollIntoView?.({behavior:'smooth',block:'start'});playBoard(tutorContent(id),'#tutor-board',false,()=>$('#similar')?.classList.add('ready'))}}
function bindCoach(id,independent){if(!$('#toggle-moli'))return;$('#toggle-moli').onclick=async()=>{if(chatBusy)return;if(!tutorOpen&&data.questions[id])return openSolution(id);captureDraft();cancelTurn();stopSpeech();tutorOpen=!tutorOpen;render();restoreDraft();if(tutorOpen){$('#toggle-moli').focus();playBoard(tutorContent(id),'#tutor-board',true)}};
 if(independent||!tutorOpen||!$('#coach-form'))return;
 $('#companion-select').onchange=async e=>{captureDraft();cancelTurn();stopSpeech();if(await act('companion',{id:e.target.value}))restoreDraft()};
 $('#moli-joke').onclick=()=>{stopSpeech();startThink();const c=companionFor(state.companion),el=$('#playful-line');el.hidden=false;el.textContent=w(c.jokeTr,c.jokeEn);speak(el.textContent)};
 $('#play-tutor').onclick=()=>{voice=true;playBoard(tutorContent(id),'#tutor-board',!data.support?.[id]?.full)};$('#pause-tutor').onclick=()=>{stopSpeech();startThink()};
 $('#coach-form').onsubmit=async e=>{e.preventDefault();if(chatBusy||busy)return;if(!turnReady)return notice(w('MOLİ önce düşünmen için 10 saniye bekliyor.','MOLİ is waiting ten seconds for you to think.'));const text=$('#coach-input').value.trim();if(!text)return;captureDraft();coachError='';stopSpeech();if(local){coachError=errorText('ai_not_configured');$('#coach-error').textContent=coachError;return}chatBusy=true;$('#coach-submit').disabled=true;$('#coach-submit').textContent=w('MOLİ düşünüyor…','MOLİ is thinking…');const requestPhase=state.units[id].mode;try{const r=await fetch('/api/tutor',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic:id,text,language:lang})}),j=await r.json();if(!r.ok)throw new Error(j.error);await refresh();if(page==='route'&&selected===id&&state.units[id].mode===requestPhase){boardMode='ai';revealed=0;tutorOpen=true;render();restoreDraft();$('#coach-input').value='';playBoard(j.reply,'#tutor-board',true)}}catch(e){coachError=errorText(e.message);try{await refresh()}catch{}if(page==='route'&&selected===id){render();restoreDraft()}}finally{chatBusy=false;if($('#coach-submit')){$('#coach-submit').disabled=!turnReady;$('#coach-submit').textContent=w('Sıra MOLİ’de →','MOLİ’s turn →')}}};$('#coach-mic').onclick=()=>startMicrophone('coach-input');
}
function startMicrophone(target){const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API)return notice(w('Bu tarayıcı sesle yazmayı desteklemiyor. Yazarak devam edebilirsin.','This browser cannot transcribe speech. Please type instead.'));mic?.abort();stopSpeech();if(target==='coach-input'&&!turnReady&&!turnDeadline)startThink();mic=new API();mic.lang=lang==='tr'?'tr-TR':'en-US';mic.onresult=e=>{const el=$('#'+target);if(el){el.value=target==='answer-value'?mathFromSpeech(e.results[0][0].transcript,lang):e.results[0][0].transcript;if(target==='answer-value')answerPreview();notice(w('Konuşman yazıya çevrildi. Kontrol edip kendin gönder.','Speech transcribed. Review it and send when ready.'))}};mic.onerror=e=>{if(e.error!=='aborted')notice(w('Mikrofon iznini kontrol et.','Check microphone permission.'))};notice(w('Tarayıcın sesi yazıya çevirir; ses sağlayıcıya iletilebilir. Otomatik gönderim yapılmaz.','Your browser transcribes speech and may send audio to its provider. Nothing is submitted automatically.'));mic.start()}
function errorText(code){return ({ai_not_configured:w('Canlı MOLİ bağlantısı henüz etkin değil. Bağlantı kurulmadan sana hazır bir paragrafı AI yanıtı gibi tekrarlamayacağım.','Live MOLİ is not connected yet. Prepared paragraphs will not be presented as AI replies.'),ai_credits_required:w('MOLİ bağlantısı için AI hesabında kullanım kredisi gerekiyor.','The AI account needs available credits.'),ai_activation_required:w('AI hizmetinde hesap etkinleştirmesi gerekiyor.','The AI service requires account activation.'),ai_auth_required:w('AI bağlantısının yetkilendirmesi tamamlanmalı.','AI connection authentication needs setup.'),rate_limited:w('Kısa bir süre bekleyip tekrar sorabilirsin.','Please wait briefly before asking again.'),reload_required:w('Ders kaydı başka bir sekmede değişti. Sorunu yeniden gönderebilirsin.','The lesson changed in another tab. You can resend your question.')})[code]||w('MOLİ şu an yanıt veremedi. Sorun burada kaldı; tekrar deneyebilirsin.','MOLİ could not reply. Your question is preserved so you can retry.')}
let calcDraft='';
function bindTools(){if($('#math-keyboard'))$('#math-keyboard').onclick=()=>{toolOpen=toolOpen==='keyboard'?'':'keyboard';renderTools()};if($('#calculator'))$('#calculator').onclick=()=>{toolOpen=toolOpen==='calculator'?'':'calculator';renderTools()};renderTools()}
function renderTools(){const host=$('#math-tools');if(!host)return;const independent=page==='discover'||state.units[selected]?.mode==='test'||pendingQuestion?.u?.mode==='test';
 if(!toolOpen){host.innerHTML='';return}
 if(toolOpen==='calculator'&&independent){host.innerHTML=`<section class="math-tool"><div class="tool-head"><b>${w('Hesap makinesi','Calculator')}</b>${button('×','close-tool',true)}</div><p>${w('Seviye tespitinde ve bağımsız testte kendi işlem becerini görmek için hesap makinesi kapalı. Ders ve birlikte çözümde açılır.','The calculator is off during assessment and independent tests. It is available in lessons and guided practice.')}</p></section>`;$('#close-tool').onclick=()=>{toolOpen='';renderTools()};return}
 const calculator=toolOpen==='calculator';host.innerHTML=`<section class="math-tool"><div class="tool-head"><b>${calculator?w('Hesap makinesi','Calculator'):w('Matematik klavyesi','Math keyboard')}</b>${button('×','close-tool',true)}</div>${calculator?`<label class="field">${w('İşlem','Expression')}<input id="calc-expression" maxlength="200" autocomplete="off" value="${esc(calcDraft)}" placeholder="(12 + 6) ÷ 3"></label><output id="calc-result" aria-live="polite"></output>`:!$('#answer-value')?`<label class="field">${w('Karalama alanı','Scratch space')}<input id="math-scratch" maxlength="100" autocomplete="off"></label>`:`<p class="subtle">${w('Semboller cevabına eklenir. Kesir için pay ve paydayı parantezlere yaz.','Symbols are inserted into your answer. Put numerator and denominator inside the brackets.')}</p>`}<div class="math-key-grid">${[['7','7'],['8','8'],['9','9'],['÷','/'],['4','4'],['5','5'],['6','6'],['×','*'],['1','1'],['2','2'],['3','3'],['−','-'],['0','0'],[',',','],['(', '('],[')',')'],['+', '+'],['a²','^2'],['aⁿ','^()'],['√','sqrt()'],['½','()/()'],['π','pi'],['⌫','back'],['C','clear']].map(([label,key])=>`<button type="button" class="math-key" data-insert="${key}" aria-label="${esc(label)}">${label}</button>`).join('')}</div>${calculator?`<div class="actions">${button(w('Hesapla =','Calculate ='),'calc-equals')}${$('#answer-value')?button(w('Sonucu cevabıma ekle','Use result as my answer'),'use-result',true):''}</div><p class="subtle">${w('Bu bir çalışma aracı. Önce nasıl çözeceğini düşün, sonra işlemini kontrol et.','A learning tool: plan your approach first, then check your arithmetic.')}</p>`:''}</section>`;
 $('#close-tool').onclick=()=>{toolOpen='';renderTools()};const target=()=>calculator?$('#calc-expression'):$('#answer-value')||$('#math-scratch');
 host.querySelectorAll('[data-insert]').forEach(b=>b.onclick=()=>{const el=target();if(!el||el.disabled)return;const key=b.dataset.insert;let start=el.selectionStart??el.value.length,end=el.selectionEnd??start,value=el.value;
 if(key==='clear'){el.value='';start=0}else if(key==='back'){el.value=value.slice(0,start===end?Math.max(0,start-1):start)+value.slice(end);start=Math.max(0,start-1)}else{el.value=(value.slice(0,start)+key+value.slice(end)).slice(0,calculator?200:100);start+=key==='()/()'?1:key==='sqrt()'?5:key==='^()'?2:key.length}el.focus();el.setSelectionRange?.(start,start);if(calculator){calcDraft=el.value;$('#calc-result').textContent=''}else answerPreview()});
 if(calculator){let result=null;$('#calc-expression').oninput=()=>{calcDraft=$('#calc-expression').value;result=null;$('#calc-result').textContent=''};const solve=()=>{try{result=calculate($('#calc-expression').value);$('#calc-result').innerHTML=math(fraction(result));return true}catch{result=null;$('#calc-result').textContent=w('İşlemi kontrol et. Sıfıra bölme ve tamamlanmamış ifadeler hesaplanamaz.','Check the expression. Division by zero and incomplete expressions cannot be calculated.');return false}};$('#calc-equals').onclick=solve;if($('#use-result'))$('#use-result').onclick=()=>{if(solve()&&$('#answer-value')&&!$('#answer-value').disabled){$('#answer-value').value=String(Number(result.toPrecision(10)));answerPreview()}};}
}
function journeyBanner(){const r=rewardSummary(state);return `<section class="journey-banner"><div class="orbit-symbol" aria-hidden="true">✦</div><div><span class="eyebrow">${w('MATEMATİK YOLCULUĞUN','YOUR MATH JOURNEY')}</span><strong>${w(r.rank[0],r.rank[1])} · ${w('Seviye','Level')} ${r.level}</strong><span>${w(`Yeni keşif görevi: ${r.mission.current}/5 doğru · Tamamlayınca +15 XP`,`Discovery quest: ${r.mission.current}/5 correct · Finish for +15 XP`)}</span></div><button type="button" class="journey-rewards" id="journey-rewards">${r.points} XP <span>↗</span></button></section>`}
function showRewards(){cancelTurn();stopSpeech();const r=rewardSummary(state),panel=document.createElement('div');panel.className='rewards-overlay';const canPractice=selected&&state.units[selected]&&!['lesson','test'].includes(state.units[selected].mode);panel.innerHTML=`<section class="rewards-card vibrant-rewards" role="dialog" aria-modal="true" aria-labelledby="rewards-title"><div class="tool-head"><span class="eyebrow">${w('KÜÇÜK ADIMLAR, BÜYÜK KEŞİFLER','SMALL STEPS, BIG DISCOVERIES')}</span><button class="button secondary" id="close-rewards" aria-label="${w('Kapat','Close')}">×</button></div><div class="reward-hero"><span class="reward-planet" aria-hidden="true">✦</span><div><p>${w(r.rank[0],r.rank[1])}</p><h2 id="rewards-title">${w('Bir sonraki keşfin seni bekliyor.','Your next discovery awaits.')}</h2><strong>${r.points} XP</strong><span>${w('Seviye','Level')} ${r.level} · ${r.next} XP ${w('sonraki seviyeye','to the next level')}</span></div></div><div class="progress"><span style="width:${r.points%100}%"></span></div><div class="quest-card"><div><span class="eyebrow">${w('KEŞİF GÖREVİ','DISCOVERY QUEST')} ${r.mission.round}</span><h3>${w('Beş yeni fikri yakala','Find five new connections')}</h3><p>${w('Farklı soruları doğru çöz. Yeniden deneyerek ulaştığın doğrular da sayılır.','Solve different questions correctly. A correct answer after retrying counts too.')}</p></div><b>+15 XP</b><div class="quest-dots" aria-label="${r.mission.current} / 5">${Array.from({length:5},(_,i)=>`<span class="${i<r.mission.current?'complete':''}">${i<r.mission.current?'✓':i+1}</span>`).join('')}</div></div><div class="constellation"><h3>${w('Seviye rotan','Your level trail')}</h3><div>${Array.from({length:6},(_,i)=>{const level=Math.max(1,r.level-2)+i;return `<span class="${level<=r.level?'reached':''}"><b>${level<r.level?'✓':level===r.level?'✦':level}</b><small>${w('Seviye','Level')} ${level}</small></span>`}).join('')}</div></div><h3>${w('Rozet atölyen','Your badge workshop')} <small>${r.badges.filter(b=>b.earned).length}/${r.badges.length}</small></h3><div class="badge-grid">${r.badges.map((b,i)=>`<div class="badge-tile badge-color-${i%4} ${b.earned?'earned':''}"><span>${b.icon}</span><b>${w(b.tr,b.en)}</b><small>${b.earned?w('Kazanıldı ✓','Earned ✓'):Math.min(b.progress,b.target)+' / '+b.target}</small><div class="badge-meter"><i style="width:${Math.min(100,b.progress/b.target*100)}%"></i></div></div>`).join('')}</div><div class="reward-next"><p>${w('Bir doğru +10 XP. Her beş yeni doğruda görev bonusu +15 XP. Test ödülleri test sonunda açılır.','One correct answer earns 10 XP. Every five new correct answers add a 15 XP quest bonus. Test rewards unlock after completion.')}</p><button class="button" id="reward-practice">${canPractice?w('∞ Birlikte yeni soru çözelim','∞ Solve a new problem together'):w('Öğrenmeye devam →','Keep learning →')}</button></div></section>`;document.body.appendChild(panel);const previous=document.activeElement,close=()=>{panel.remove();previous?.focus()};panel.querySelector('#close-rewards').onclick=close;panel.querySelector('#reward-practice').onclick=async()=>{close();if(canPractice){pendingQuestion=null;tutorOpen=false;await act('free',{topic:selected})}else if(page!=='route')go('route')};panel.onclick=e=>{if(e.target===panel)close()};panel.onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const buttons=[panel.querySelector('#close-rewards'),panel.querySelector('#reward-practice')],at=buttons.indexOf(document.activeElement);e.preventDefault();buttons[(at+(e.shiftKey?1:1))%2].focus()}};panel.querySelector('#close-rewards').focus()}
function rampSvg(rise,run){const x=55,y=160,scale=Math.min(300/run,130/rise),end=x+run*scale,top=y-rise*scale;return `<svg width="460" height="210" viewBox="0 0 460 210" role="img" aria-label="${w('Rampanın yüksekliği','Ramp rise')} ${rise} m, ${w('yatay mesafe','horizontal run')} ${run} m"><path d="M${x} ${y}L${end} ${top}L${end} ${y}Z" fill="#dbe8cd" stroke="#6d925f" stroke-width="4"/><path d="M${x} 178H${end}M${end+25} ${top}V${y}" stroke="#b89c62" stroke-width="2" stroke-dasharray="5"/><text x="${(x+end)/2}" y="201" fill="#315449">${fmt(run)} m</text><text x="${end+35}" y="${(top+y)/2}" fill="#315449">${fmt(rise)} m</text></svg>`}
function visual(kind,q=null,interactive=false){const a=q?2+q.seed%5:2,b=q?3+(q.seed*3)%5:4;let svg='';const text=(x,y,s)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#365446" font-size="16">${esc(s)}</text>`;
 if(kind==='ramp')return `<div class="scene-diagram"><div id="ramp-drawing">${rampSvg(a,q?b*2:8)}</div>${interactive?`<div class="ramp-inputs"><label>${w('Yükseklik','Rise')} <output id="ramp-rise-value">2 m</output><input id="ramp-rise" data-ramp type="range" min="1" max="4" step=".5" value="2"></label><label>${w('Yatay mesafe','Horizontal run')} <output id="ramp-run-value">8 m</output><input id="ramp-run" data-ramp type="range" min="4" max="12" step="1" value="8"></label></div>`:''}</div>`;
 if(kind==='square'||kind==='squares'){svg=`<rect x="60" y="25" width="130" height="130" fill="#dce8cf" stroke="#78966b" stroke-width="2"/>${text(125,95,kind==='square'?`${q?a*a:50} m²`:'3 × 3')}`;if(kind==='squares')svg+=`<rect x="240" y="15" width="160" height="160" fill="#eae0c8" stroke="#b99b5f"/><path d="M320 15V175M240 95H400" stroke="#b99b5f"/>${text(320,194,'6 × 6')}`}
 else if(kind==='triangle')svg=`<path d="M70 155L235 25L390 155Z" fill="#e1ead7" stroke="#78966b" stroke-width="3"/>${text(105,145,(q?a*10:50)+'°')}${text(350,145,(q?b*10:60)+'°')}${text(235,62,'?')}`;
 else if(kind==='marbles')svg=Array.from({length:a+b},(_,i)=>`<circle cx="${60+(i%8)*45}" cy="${70+Math.floor(i/8)*55}" r="15" fill="${i<a?'#b8796b':'#7f9fae'}"/>`).join('');
 else if(kind==='bars'){const values=q?[a,a+b,a+2*b]:[12,18,24];svg=values.map((n,i)=>`<rect x="${75+i*100}" y="${160-n*4}" width="55" height="${n*4}" fill="#9bb38b"/>${text(103+i*100,150-n*4,n)}${text(103+i*100,185,w('Gün ','Day ')+(i+1))}`).join('')}
 else if(kind==='coordinates')svg=`<path d="M40 100H420M230 10V185" stroke="#a3b39a" stroke-width="2"/><path d="M230 10V185" stroke="#b89c62" stroke-width="3" stroke-dasharray="5"/><circle cx="310" cy="45" r="7" fill="#38614f"/>${text(350,40,`(${q?a:2}, ${q?b:3})`)}${text(240,195,'0')}${text(245,20,'y')}`;
 else if(kind==='cylinder')svg=`<path d="M155 55V150C155 185 315 185 315 150V55" fill="#dfead9" stroke="#78966b" stroke-width="2"/><ellipse cx="235" cy="55" rx="80" ry="30" fill="#edf3e6" stroke="#78966b" stroke-width="2"/><path d="M235 55H315" stroke="#b89c62" stroke-width="2"/>${text(275,47,`r = ${a} cm`)}${text(370,115,`h = ${q?b:5} cm`)}`;
 else if(kind==='numberline')svg=`<path d="M50 105H420" stroke="#78966b" stroke-width="3"/><path d="M65 105H290" stroke="#b89c62" stroke-width="6"/><circle cx="290" cy="105" r="8" fill="#fff" stroke="#b89c62" stroke-width="3"/>${text(290,140,'k')}${text(100,75,'x < k')}`;
 else if(kind==='balance')svg=`<path d="M235 65V160M155 165H315M90 65H380" stroke="#8ba17d" stroke-width="5"/><path d="M110 65L80 125H175L150 65M315 65L285 125H380L355 65" stroke="#8ba17d" stroke-width="2" fill="#e6eddc"/>${text(128,113,'x + …')}${text(332,113,w('toplam','total'))}`;
 else if(kind==='groups')svg=[q?a*2:24,q?b*2:36].map((n,row)=>Array.from({length:Math.min(n,36)},(_,i)=>`<rect x="${40+(i%18)*21}" y="${35+row*75+Math.floor(i/18)*20}" width="12" height="12" rx="2" fill="${row?'#bca36c':'#8fa97e'}"/>`).join('')).join('');
 else if(kind==='growth')svg=Array.from({length:3},(_,i)=>`<rect x="${45+i*140}" y="55" width="90" height="70" rx="10" fill="#e4ecd9"/>${text(90+i*140,96,i===0?'1':w('× '+(q?a:2),'× '+(q?a:2)))}`).join('');
 return `<div class="scene-diagram"><svg width="460" height="205" viewBox="0 0 460 205" role="img" aria-label="${w('Soru durumunun görsel modeli','Visual model of the situation')}">${svg}</svg></div>`;
}
function plan(){if(!state.diagnostic.done)return gate();const needsSupport=baseline(state).reduce((sum,t)=>sum+(t.score||0),0)/topics.length<50;const p=state.plan||{days:needsSupport?[1,2,4,6]:[1,3,5],time:'18:00',zone:'Europe/Istanbul',minutes:needsSupport?20:30,email:false,sms:false};const names=lang==='tr'?['Paz','Pzt','Sal','Çar','Per','Cum','Cmt']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];layout(intro(w('Birlikte düzen kuralım.','Let’s build a rhythm together.'),w(needsSupport?'Başlangıç haritana göre haftada dört kısa, 20 dakikalık çalışma öneriyorum. Sana uyan gün ve saatleri birlikte seçelim.':'Başlangıç haritana göre haftada üç, 30 dakikalık çalışma öneriyorum. Sana uyan gün ve saatleri birlikte seçelim.',needsSupport?'Your starting map suggests four short, 20-minute sessions per week. Let’s choose days and times that suit you.':'Your starting map suggests three 30-minute sessions per week. Let’s choose days and times that suit you.'))+`<div class="grid equal"><section class="card"><h2>${w('Haftalık çalışma düzenim','My weekly routine')}</h2><form id="plan-form"><label class="field">${w('Günler','Days')}</label><div class="day-picks">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="day" value="${d}" ${p.days.includes(d)?'checked':''}> ${names[d]}</label>`).join('')}</div><div class="grid equal"><label class="field">${w('Başlangıç saati','Start time')}<input type="time" id="plan-time" value="${p.time}" required></label><label class="field">${w('Süre','Duration')}<select id="plan-minutes">${[20,30,45].map(n=>`<option ${p.minutes===n?'selected':''} value="${n}">${n} ${w('dakika','minutes')}</option>`).join('')}</select></label></div><label class="field">${w('Saat dilimi','Time zone')}<select id="plan-zone">${['Europe/Istanbul','America/New_York','Europe/London','UTC'].map(z=>`<option ${p.zone===z?'selected':''}>${z}</option>`).join('')}</select></label><h3>${w('10 dakika önce hatırlat','Remind me 10 minutes before')}</h3><label class="check"><input id="email-reminder" type="checkbox" ${p.email?'checked':''} ${!data.capabilities.email?'disabled':''}>${w('Doğrulanmış hesap e-postama hatırlatma gönder.','Send reminders to my verified account email.')}</label>${!data.capabilities.email?`<p class="subtle">${w('E-posta hatırlatma servisi henüz etkinleştirilmedi.','Email reminder delivery is not activated yet.')}</p>`:''}<label class="check"><input id="sms-reminder" type="checkbox" ${p.sms?'checked':''} ${!data.capabilities.phoneVerified||!data.capabilities.sms?'disabled':''}>${w('Doğruladığım telefonuma SMS gönder.','Send SMS to my verified phone.')}</label>${data.capabilities.sms?phoneForm():`<p class="subtle">${w('SMS için telefon doğrulama ve gönderim servisi henüz etkin değil.','Phone verification and SMS delivery are not activated yet.')}</p>`}<button class="button" type="submit">${w('Planımı kaydet','Save my plan')}</button></form><div class="actions">${button(w('Takvimime indir (.ics)','Download calendar (.ics)'),'calendar',true)}</div></section><section class="card"><h2>${w('Yaklaşan çalışmalarım','My upcoming sessions')}</h2>${state.plan?nextSessions(state.plan).map(iso=>`<div class="session"><strong>${date(iso)}</strong><p class="subtle">${state.plan.minutes} ${w('dakika','minutes')} · ${esc(title(state.order.find(id=>!state.units[id]?.passed)||state.order[0]))}</p></div>`).join(''):`<p class="empty">${w('Planını kaydettiğinde çalışma saatlerin burada görünecek.','Save your plan to see upcoming sessions here.')}</p>`}<p class="subtle">${w('Takvim dosyası 10 dakika öncesine alarm ekler. Alarmın gösterimi takvim uygulamanın ayarlarına bağlıdır.','The calendar file includes a 10-minute reminder. Delivery depends on your calendar app settings.')}</p></section></div>`);
 $('#plan-form').onsubmit=async e=>{e.preventDefault();const days=[...root.querySelectorAll('input[name=day]:checked')].map(x=>+x.value);if(!days.length){notice(w('En az bir gün seç.','Choose at least one day.'));return}if(await act('plan',{days,time:$('#plan-time').value,minutes:+$('#plan-minutes').value,zone:$('#plan-zone').value,email:$('#email-reminder').checked,sms:$('#sms-reminder').checked}))notice(w('Çalışma planın kaydedildi.','Your study plan is saved.'))};$('#calendar').onclick=()=>{if(!state.plan)return notice(w('Önce planını kaydet.','Save your plan first.'));const stamp=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const entries=nextSessions(state.plan,new Date(),20).map(iso=>`BEGIN:VEVENT\r\nUID:${user?.id||'demo'}-${stamp(iso)}@moli\r\nDTSTAMP:${stamp(new Date())}\r\nDTSTART:${stamp(iso)}\r\nDTEND:${stamp(new Date(+new Date(iso)+state.plan.minutes*60000))}\r\nSUMMARY:MOLI mathematics\r\nBEGIN:VALARM\r\nTRIGGER:-PT10M\r\nACTION:DISPLAY\r\nDESCRIPTION:MOLI study session\r\nEND:VALARM\r\nEND:VEVENT`);download('moli-plan.ics','BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//MOLI//Study//TR\r\n'+entries.join('\r\n')+'\r\nEND:VCALENDAR\r\n','text/calendar')};bindPhone();
}
function phoneForm(){return `<details><summary>${w('SMS telefon doğrulaması','Verify phone for SMS')}${data.capabilities.phoneVerified?' ✓':''}</summary><label class="field">${w('Uluslararası telefon (+90…)','International phone (+90…)')}<input id="phone" type="tel" value="${esc(data.capabilities.phone||'')}" placeholder="+905XXXXXXXXX"></label>${button(w('Kod gönder','Send code'),'phone-send',true)}<label class="field">${w('Doğrulama kodu','Verification code')}<input id="phone-code" inputmode="numeric" maxlength="8"></label>${button(w('Telefonumu doğrula','Verify my phone'),'phone-check',true)}</details>`}
function bindPhone(){for(const [id,action]of [['phone-send','send'],['phone-check','check']])if($('#'+id))$('#'+id).onclick=async()=>{const b=$('#'+id);b.disabled=true;try{const r=await fetch('/api/phone',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,phone:$('#phone').value,code:$('#phone-code').value})});if(!r.ok)throw new Error();notice(w(action==='send'?'Kod gönderildi.':'Telefon doğrulandı.',action==='send'?'Code sent.':'Phone verified.'));if(action==='check'){await refresh();render()}}catch{notice(w('Doğrulama tamamlanamadı. Numara/kodu kontrol et veya biraz sonra dene.','Verification failed. Check the number/code or try again later.'))}finally{b.disabled=false}}}
const eventName=k=>({explanation_step:w('Tahtada anlatım adımı','Board explanation step'),guided_hint:w('Birlikte çözüm desteği','Guided solution support'),independent_test_started:w('Bağımsız test başladı','Independent test started'),board_note:w('Tahta notu kaydedildi','Board note saved'),lesson_review:w('Ders tekrarı','Lesson review'),assessment_started:w('Seviye belirleme başladı','Assessment started'),diagnostic_answer:w('Başlangıç sorusu cevaplandı','Assessment answer saved'),assessment_completed:w('Başlangıç haritası hazır','Assessment completed'),lesson_opened:w('Ders açıldı','Lesson opened'),answer:w('Soru cevaplandı','Question answered'),test_completed:w('Test tamamlandı','Test completed'),extra_test:w('Ek test başladı','Extra test started'),plan_saved:w('Çalışma planı kaydedildi','Study plan saved')})[k]||k;
function progress(){const passed=Object.values(state.units).filter(u=>u.passed).length,attempts=Object.values(state.units).flatMap(u=>u.attempts);layout(intro(w('Attığın her adım burada.','Every step lives here.'),w('Gerçek cevapların, testlerin ve çalışma geçmişin. İstersen seçtiğin kayıtları indirip öğretmenin veya velinle paylaşabilirsin.','Your answers, tests and activity history. Download selected records to share with your teacher or guardian.'))+`<div class="stats"><div class="stat"><b>${passed}/${topics.length}</b><span>${w('Tamamlanan konu','Topics completed')}</span></div><div class="stat"><b>${attempts.length}</b><span>${w('Tamamlanan test','Completed tests')}</span></div><div class="stat"><b>${state.activeMinutes}</b><span>${w('Etkin çalışma dakikası (yaklaşık)','Active study minutes (approx.)')}</span></div></div><div class="grid"><section class="card"><h2>${w('Başlangıçtan bugüne','From your starting point to today')}</h2>${state.diagnostic.done?`<div class="bars">${baseline(state).map(t=>{const u=state.units[t.id],score=u?.attempts.at(-1)?.score;return `<div class="bar-label"><span>${esc(t.title[lang])}</span><span>${t.score}% → <b>${score===undefined?w('henüz test yok','no test yet'):score+'%'}</b></span></div>`}).join('')}</div>`:`<p class="empty">${w('Başlangıç değerlendirmeni tamamlayınca karşılaştırman açılır.','Complete the starting assessment to see comparisons.')}</p>`}<p class="subtle">${w('Başlangıç soruları ve konu testleri farklı örneklemlerdir; karşılaştırma resmî ölçüm değildir.','Initial questions and topic tests use different samples; comparisons are not standardized measurements.')}</p></section><section class="card"><h2>${w('Paylaşmak istediğini seç','Choose what to share')}</h2><label class="check"><input type="checkbox" id="export-scores" checked>${w('Konu ve test sonuçları','Topic and test results')}</label><label class="check"><input type="checkbox" id="export-answers">${w('Cevaplarım ve açıklamalarım','My answers and reasoning')}</label><label class="check"><input type="checkbox" id="export-messages">${w('MOLİ konuşma dökümü','MOLİ conversation transcript')}</label><label class="check"><input type="checkbox" id="export-plan">${w('Çalışma planım','My study plan')}</label><div class="actions">${button(w('Raporu indir (.txt)','Download report (.txt)'),'export')}${button(w('Tam yedeği indir (.json)','Download full backup (.json)'),'backup',true)}</div><p class="subtle">${w('İndirme kimseye otomatik göndermez. Dosyayı seçtiğin kişiyle kendin paylaşabilirsin.','Downloading does not send records to anyone. Share the file with your chosen person yourself.')}</p></section></div><section class="card"><h2>${w('Son etkinliklerin','Recent activity')}</h2>${state.activity.length?[...state.activity].reverse().slice(0,50).map(a=>`<div class="timeline"><span>${eventName(a.kind)} ${a.topic?'· '+esc(title(a.topic)):''}${a.score!==undefined?' · '+a.score+'%':''}</span><time>${date(a.at)}</time></div>`).join(''):`<p class="empty">${w('İlk adımını bekliyoruz.','Your first step is waiting.')}</p>`}<p class="subtle">${w('Son 1.000 etkinlik ve son 600 konuşma mesajı tutulur.','The latest 1,000 activity events and 600 conversation messages are retained.')}</p></section>`);
 $('#export').onclick=()=>{const lines=['MOLİ · '+w('Öğrenme raporu','Learning report'),w('Görünen ad: ','Display name: ')+(user?.name||'Demo'),new Date().toISOString()];if($('#export-scores').checked){lines.push('\n'+w('BAŞLANGIÇ VE TEST SONUÇLARI','BASELINE AND TEST RESULTS'));for(const t of baseline(state))lines.push(title(t.id)+': '+w('Başlangıç ','Initial ')+(t.score??'—')+'%; '+(state.units[t.id]?.attempts.map(a=>date(a.at)+' '+a.score+'%').join(', ')||'—'))}if($('#export-answers').checked){lines.push('\n'+w('YANITLAR VE AÇIKLAMALAR (açıklamalar rubrikle puanlanmadı)','ANSWERS AND REASONING (reasoning not rubric graded)'));for(const a of [...state.diagnostic.answers,...Object.values(state.units).flatMap(u=>u.answers)])lines.push(`${a.id}: ${a.value} | ${a.reason||''} | ${a.correct?'✓':'–'}`)}if($('#export-answers').checked){lines.push('\n'+w('TAHTA NOTLARIM','MY BOARD NOTES'));for(const [id,u]of Object.entries(state.units))if(u.notes)lines.push(title(id)+': '+u.notes)}if($('#export-messages').checked){lines.push('\n'+w('KONUŞMALAR','CONVERSATIONS'));state.messages.forEach(m=>lines.push(`${date(m.at)} ${m.role}: ${m.text}`))}if($('#export-plan').checked)lines.push('\n'+JSON.stringify(state.plan,null,2));download('moli-rapor.txt',lines.join('\n'),'text/plain')};$('#backup').onclick=()=>download('moli-kayitlar.json',JSON.stringify({displayName:user?.name||'Demo',exportedAt:new Date().toISOString(),...state},null,2),'application/json');
}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){mic?.abort();cancelTurn();stopSpeech();if(!['discover','route','plan','progress'].includes(page))page='discover';prepare(state);({discover,route,plan,progress}[page])()}
async function start(){try{const demo=new URLSearchParams(location.search).get('demo')==='1';if(!demo){const r=await sessionRequest('session');if(!r.user){location.replace('/');return}user=r.user;if(user.role==='teacher'){location.replace('/teacher');return}lang=user.language||'tr'}else{try{lang=localStorage.getItem('moli.language')==='en'?'en':'tr'}catch{}}localKey='moli.learning.v1.'+(user?.id||'demo');if(demo){local=true}else{try{await refresh()}catch(e){if(e.message==='session_expired'){location.replace('/');return}if(e.message!=='learning_setup_required')throw e;local=true}}
 if(local){let saved;try{saved=JSON.parse(localStorage.getItem(localKey)||'null')}catch{}state=saved?.version===1?saved:initial();data=localView()}render();window.addEventListener('hashchange',()=>{cancelTurn();tutorOpen=false;pendingQuestion=null;lessonAuto=false;page=location.hash.slice(1)||'discover';selected='';feedback=null;boardMode='lesson';revealed=0;stopSpeech();render();window.scrollTo(0,0)});let lastActivity=Date.now();for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>lastActivity=Date.now());setInterval(()=>{if(document.visibilityState==='visible'&&Date.now()-lastActivity<120000&&!busy&&!chatBusy)act('minutes')},60000);
 }catch{root.innerHTML=`<main class="loading"><h1>${w('Öğrenme alanına ulaşılamıyor.','Learning records are unavailable.')}</h1><p>${w('Bağlantı hatasında mevcut kayıtlarının üzerine yazmayız. Lütfen yeniden dene.','Your saved records are not overwritten when a connection fails. Please retry.')}</p><button class="button" onclick="location.reload()">${w('Yeniden dene','Try again')}</button></main>`}}
start();
